// ═══════════════════════════════════════════════════════════════════════════════
// Email Service — Resend (primary, HTTPS/443) → SMTP fallback → mock
// ═══════════════════════════════════════════════════════════════════════════════
//
// Transactional emails sent for:
//   1.  Welcome / email-verification   — on sign-up
//   2.  Subscription confirmation       — on IAP purchase (Apple / Google)
//   3.  Payment receipt                 — on each successful renewal
//   4.  Payment failure warning         — on failed billing
//   5.  Cancellation confirmation       — on subscription cancellation
//   6.  Subscription reactivated/renewed
//
// Design: matches huddlapp.co.uk — warm peach body, Huddl orange (#FCA878)
//   CTA buttons, inline SVG/PNG illustrations from the app asset library.
//
// Provider priority:
//   1. Resend (RESEND_API_KEY set)          — pure HTTPS port 443
//   2. Nodemailer SMTP (SMTP_* env vars)    — fallback
//   3. Mock logger                          — development / no credentials
// ═══════════════════════════════════════════════════════════════════════════════

'use strict';

const nodemailer = require('nodemailer');

// ── Provider selection ────────────────────────────────────────────────────────
let resendClient = null;
let transporter  = null;

if (process.env.RESEND_API_KEY) {
  const { Resend } = require('resend');
  resendClient = new Resend(process.env.RESEND_API_KEY);
  console.log('Email provider: Resend ✓');
} else if (process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS) {
  const smtpPort = parseInt(process.env.SMTP_PORT || '465');
  transporter = nodemailer.createTransport({
    host    : process.env.SMTP_HOST,
    port    : smtpPort,
    secure  : smtpPort === 465,
    auth    : { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
    connectionTimeout : 10000,
    greetingTimeout   : 10000,
    socketTimeout     : 30000,
    family  : 4,
  });
  transporter.verify((err) => {
    if (err) console.error('[SMTP] Verification failed:', err.message);
    else console.log(`Email provider: Hostinger SMTP ✓ (${process.env.SMTP_HOST}:${smtpPort})`);
  });
} else {
  console.log('Email provider: mock (no credentials set)');
}

const FROM_EMAIL   = process.env.RESEND_FROM_EMAIL || process.env.SMTP_USER || 'welcome@huddlapp.co.uk';
const FROM_NAME    = 'Huddl';
const FRONTEND_URL = process.env.FRONTEND_URL || 'https://www.huddlapp.co.uk';

// ── Brand tokens ──────────────────────────────────────────────────────────────
// BRAND PALETTE  (corrected to match lib/theme/huddl_colors.dart — HuddlColors)
// Replaces the old off-brand object that used #FCA878 (pale peach) as primary
// and #3580F0 (website blue) as accent. Now uses the real app tokens.
const B = {
  primary      : '#FF965C',   // HuddlColors.primary — THE brand orange (buttons, accents)
  primaryDark  : '#F2743A',   // connectRingDeep — pressed/hover, gradient end
  primaryLight : '#FFC7A8',   // primaryPale — soft tint / hairlines
  accent       : '#FF965C',   // was website blue #3580F0 — now orange (no blue anywhere)
  peachBg      : '#FFF3ED',   // peachSurface — outer email background
  peachLight   : '#FFF5F0',   // peachWarm — footer / soft panels
  dark         : '#1A1A1A',   // neutral900 — headings (near-black)
  text         : '#43464D',   // textDark — body copy
  textLight    : '#6C6C6C',   // neutral600 — captions / footer (readable, not washed out)
  white        : '#FFFFFF',   // neutral0
  success      : '#199A85',   // brandTeal — the "verified / you're in" accent
  successBg    : '#E6F5F3',   // tealBg — soft success panel
  error        : '#FF5151',   // HuddlColors.error
  warningBg    : '#FEF3C7',   // warningBg
  warningBorder: '#F59E0B',   // warning
};

// ── Inline illustration data-URIs (PNG assets from the app) ──────────────────
// onboarding_welcome_illustration.png  — 4 joyful people celebrating
const ILLUS_WELCOME    = 'https://www.huddlapp.co.uk/email/hero_welcome.png';
// onboarding_two_people_illustration.png — two people high-fiving / connecting
const ILLUS_TWO_PEOPLE = 'data:image/png;base64,';
// onboarding_chat_illustration.png       — two people chatting across speech bubbles
const ILLUS_CHAT       = 'data:image/png;base64,';
// Group_3603.png                         — single person waving / reaching up
const ILLUS_WAVE       = 'data:image/png;base64,';

// ── Real Huddl logo (assets/images/logo_huddl.png) ──────────────────────────
// Two-tone orange H-mark + rounded dark-grey "huddl" wordmark, transparent bg.
// Base64-embedded PNG — do NOT reconstruct with CSS text (custom typeface).
// Display width ~150px (aspect ratio ~3.59:1).
const HUDDL_LOGO = 'https://www.huddlapp.co.uk/email/logo.png';

function _logoSvg() {
  return `<img src="${HUDDL_LOGO}" alt="huddl" width="150"
            style="display:block;width:150px;height:auto;margin:0 auto;"/>`;
}

// ── Shared helpers ────────────────────────────────────────────────────────────

/**
 * Wraps body HTML in the Huddl email shell — minimalist (Airbnb/Spotify style).
 * No coloured header bar. Small orange wordmark on white card over peach bg.
 * One brand-colour moment = the CTA button. Everything else near-black on white.
 */
function _wrap(title, bodyHtml) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8"/>
  <meta name="viewport" content="width=device-width,initial-scale=1.0"/>
  <meta name="color-scheme" content="light only"/>
  <meta name="supported-color-schemes" content="light"/>
  <title>${title}</title>
  <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700;800;900&display=swap" rel="stylesheet"/>
</head>
<body style="margin:0;padding:0;background:${B.peachBg};
             font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,
             Helvetica,Arial,sans-serif;-webkit-text-size-adjust:100%;">

  <table width="100%" cellpadding="0" cellspacing="0" role="presentation"
         style="background:${B.peachBg};padding:48px 16px;">
    <tr>
      <td align="center">

        <!-- Real Huddl logo (assets/images/logo_huddl.png) above the card -->
        <table cellpadding="0" cellspacing="0" role="presentation" style="margin:0 auto 22px;">
          <tr><td style="text-align:center;">${_logoSvg()}</td></tr>
        </table>

        <!-- White card -->
        <table width="560" cellpadding="0" cellspacing="0" role="presentation"
               style="max-width:560px;background:${B.white};border-radius:20px;
                      overflow:hidden;box-shadow:0 2px 16px rgba(26,26,26,0.06);">

          <!-- BODY -->
          <tr>
            <td style="padding:40px 40px 32px;">
              ${bodyHtml}
            </td>
          </tr>

        </table>
        <!-- /Card -->

        <!-- Footer — muted, outside the card -->
        <table width="560" cellpadding="0" cellspacing="0" role="presentation"
               style="max-width:560px;margin:20px auto 0;">
          <tr>
            <td style="text-align:center;padding:0 24px;">
              <p style="margin:0 0 6px;font-size:12px;color:${B.textLight};">
                Cruzen Ltd &middot; London, UK
              </p>
              <p style="margin:0;font-size:12px;color:${B.textLight};">
                <a href="${FRONTEND_URL}/privacy"
                   style="color:${B.textLight};text-decoration:underline;">Privacy</a>
                &nbsp;&middot;&nbsp;
                <a href="${FRONTEND_URL}/terms"
                   style="color:${B.textLight};text-decoration:underline;">Terms</a>
              </p>
            </td>
          </tr>
        </table>

      </td>
    </tr>
  </table>
</body>
</html>`;
}


/** Orange CTA button — pill style matching the website. */
function _btn(label, url) {
  return `
    <table cellpadding="0" cellspacing="0" role="presentation" style="margin:24px 0;">
      <tr>
        <td style="background:${B.primary};border-radius:50px;padding:0;">
          <a href="${url}"
             style="display:inline-block;padding:14px 40px;color:${B.white};
                    font-weight:800;font-size:15px;text-decoration:none;
                    border-radius:50px;letter-spacing:0.3px;">${label}</a>
        </td>
      </tr>
    </table>`;
}

/** Peach info card (plan details, receipts). */
function _card(rows) {
  const trs = rows.map(r => `
    <tr>
      <td style="padding:10px 0;font-size:14px;color:${B.text};
                  border-bottom:1px solid ${B.primaryLight};">${r.label}</td>
      <td style="padding:10px 0;font-size:14px;color:${B.dark};font-weight:600;
                  text-align:right;border-bottom:1px solid ${B.primaryLight};">${r.value}</td>
    </tr>`).join('');
  return `
    <table width="100%" cellpadding="0" cellspacing="0" role="presentation"
           style="background:${B.peachLight};border-radius:14px;
                  padding:4px 20px;margin:20px 0;">
      ${trs}
    </table>`;
}

/** Horizontal divider. */
function _divider() {
  return `<hr style="border:none;border-top:1px solid ${B.primaryLight};margin:24px 0;"/>`;
}

/**
 * Illustration block — centred image with optional max-width.
 * src should be a data-URI or HTTPS URL.
 */
function _illus(src, alt, maxWidth = '220px') {
  return `
    <div style="text-align:center;margin:0 0 28px;">
      <img src="${src}" alt="${alt}"
           width="220"
           style="max-width:${maxWidth};height:auto;display:inline-block;"/>
    </div>`;
}

